#include <iostream>
#include <vector>
#include <utility>
using namespace std;
struct Node { long long value; int left, right; };
class Tree {
    vector<Node> nodes;
public:
    explicit Tree(int n) : nodes(n + 1) {}
    void read() { for (size_t i=1;i<nodes.size();++i) cin >> nodes[i].value >> nodes[i].left >> nodes[i].right; }
    pair<int,long long> visit(int id) const {
        if (id == 0) return {0, 0};
        auto left = visit(nodes[id].left);
        auto right = visit(nodes[id].right);
        return {1 + left.first + right.first, nodes[id].value + left.second + right.second};
    }
};
int main() { int n; if (!(cin >> n) || n<0 || n>1000) return 0; Tree tree(n); tree.read(); auto result=tree.visit(n ? 1 : 0); cout << result.first << ' ' << result.second << '\n'; }

