#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n, capacity; if(!(cin>>n>>capacity)||n<0||n>100||capacity<0||capacity>1000) return 0;
    vector<long long> dp(capacity+1,0);
    for(int i=0;i<n;++i) { int weight; long long value; cin>>weight>>value; if(weight<1||value<0) return 0;
        for(int c=capacity;c>=weight;--c) dp[c]=max(dp[c],dp[c-weight]+value);
    }
    cout<<dp[capacity]<<'\n';
}

